"use client";

import { useEffect, useMemo, useState } from "react";
import Link from "next/link";
import AppShell from "@/components/Navbar";
import { api } from "@/lib/api";

type RequestStatus = "Pending" | "Approved" | "Rejected" | "Cancelled" | "Released";

interface RequestItem {
  id: number;
  status: RequestStatus;
  preferred_day_of_week?: string;
  preferred_start_time?: string;
  preferred_end_time?: string;
  expected_students?: number;
  created_at?: string;
  section?: { section_name?: string };
  course?: { course_code?: string; course_title?: string };
  room?: { room_number?: string; building?: string; capacity?: number };
  instructor?: { first_name?: string; last_name?: string };
}

interface RequestListResponse {
  success: boolean;
  message: string;
  data: RequestItem[];
  meta: { total: number; page: number; per_page: number };
}

export default function AdminRequestsPage() {
  const [rows, setRows] = useState<RequestItem[]>([]);
  const [meta, setMeta] = useState({ total: 0, page: 1, per_page: 15 });
  const [page, setPage] = useState(1);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [search, setSearch] = useState("");
  const [statusFilter, setStatusFilter] = useState<RequestStatus | "All">("All");

  async function fetchData() {
    try {
      setLoading(true);
      setError(null);
      const qs = new URLSearchParams({ page: String(page) });
      if (statusFilter !== "All") qs.set("status", statusFilter);
      const res = await api.get<RequestListResponse>(`/admin/requests?${qs.toString()}`);
      setRows(res.data ?? []);
      setMeta(res.meta ?? { total: 0, page, per_page: 15 });
    } catch (e) {
      setError(e instanceof Error ? e.message : "Failed to load requests.");
    } finally {
      setLoading(false);
    }
  }

  useEffect(() => { fetchData(); }, [page, statusFilter]);

  async function review(id: number, action: "approve" | "reject") {
    try {
      setError(null);
      await api.post(`/admin/requests/${id}/${action}`, { remarks: action === "approve" ? "Approved by admin." : "Rejected by admin." });
      await fetchData();
    } catch (e) {
      setError(e instanceof Error ? e.message : `Failed to ${action} request.`);
    }
  }

  const filtered = useMemo(() => {
    if (!search.trim()) return rows;
    const q = search.toLowerCase();
    return rows.filter((r) =>
      String(r.id).includes(q) ||
      `${r.instructor?.first_name ?? ""} ${r.instructor?.last_name ?? ""}`.toLowerCase().includes(q) ||
      (r.section?.section_name ?? "").toLowerCase().includes(q) ||
      (r.course?.course_code ?? "").toLowerCase().includes(q) ||
      (r.room?.room_number ?? "").toLowerCase().includes(q)
    );
  }, [rows, search]);

  const totalPages = Math.max(1, Math.ceil(meta.total / meta.per_page));

  return (
    <AppShell role="admin" userName="Admin" pageTitle="Room Requests">
      <div className="space-y-4">
        <p className="text-sm" style={{ color: "var(--color-text-secondary)" }}>Review and act on instructor room booking requests.</p>

        <div className="card card-body grid grid-cols-1 md:grid-cols-3 gap-3">
          <input placeholder="Search instructor, section, room..." value={search} onChange={(e) => setSearch(e.target.value)} />
          <select value={statusFilter} onChange={(e) => { setStatusFilter(e.target.value as RequestStatus | "All"); setPage(1); }}>
            <option value="All">All Statuses</option>
            <option value="Pending">Pending</option>
            <option value="Approved">Approved</option>
            <option value="Rejected">Rejected</option>
            <option value="Cancelled">Cancelled</option>
            <option value="Released">Released</option>
          </select>
        </div>

        {error && <div className="rounded-lg border px-3 py-2 text-[12px]" style={{ borderColor: "#fecaca", background: "#fff1f2", color: "#9f1239" }}>{error}</div>}

        <div className="card overflow-x-auto">
          <table className="table-base">
            <thead>
              <tr><th>ID</th><th>Instructor</th><th>Section/Course</th><th>Room</th><th>Schedule</th><th>Status</th><th>Submitted</th><th></th></tr>
            </thead>
            <tbody>
              {filtered.map((r) => (
                <tr key={r.id}>
                  <td>#{r.id}</td>
                  <td>{`${r.instructor?.first_name ?? ""} ${r.instructor?.last_name ?? ""}`.trim() || "N/A"}</td>
                  <td>
                    <p>{r.section?.section_name ?? "N/A"}</p>
                    <p className="text-xs" style={{ color: "var(--color-text-muted)" }}>{r.course?.course_code ?? ""} {r.course?.course_title ? `- ${r.course.course_title}` : ""}</p>
                  </td>
                  <td>{r.room?.room_number ?? "TBA"} <span className="text-xs" style={{ color: "var(--color-text-muted)" }}>{r.room?.building ?? ""}</span></td>
                  <td>{r.preferred_day_of_week ?? ""} {r.preferred_start_time?.slice(0, 5)}-{r.preferred_end_time?.slice(0, 5)}</td>
                  <td>{r.status}</td>
                  <td>{r.created_at ? new Date(r.created_at).toLocaleString("en-US") : "-"}</td>
                  <td>
                    <div className="flex gap-1">
                      <Link href={`/admin/requests/${r.id}`} className="btn btn-sm btn-ghost">View</Link>
                      {r.status === "Pending" && (
                        <>
                          <button className="btn btn-sm" style={{ background: "var(--color-primary-muted)", color: "var(--color-primary)" }} onClick={() => review(r.id, "approve")}>Approve</button>
                          <button className="btn btn-sm" style={{ background: "var(--color-error-light)", color: "var(--color-error)" }} onClick={() => review(r.id, "reject")}>Reject</button>
                        </>
                      )}
                    </div>
                  </td>
                </tr>
              ))}
              {!loading && filtered.length === 0 && <tr><td colSpan={8} className="text-center py-10">No requests found.</td></tr>}
            </tbody>
          </table>
        </div>

        <div className="flex items-center justify-between">
          <p className="text-xs" style={{ color: "var(--color-text-muted)" }}>Page {meta.page} of {totalPages}</p>
          <div className="flex gap-2">
            <button className="btn btn-outline btn-sm" disabled={page <= 1} onClick={() => setPage((p) => Math.max(1, p - 1))}>Previous</button>
            <button className="btn btn-outline btn-sm" disabled={page >= totalPages} onClick={() => setPage((p) => Math.min(totalPages, p + 1))}>Next</button>
          </div>
        </div>
      </div>
    </AppShell>
  );
}
